1. use vstd::arithmetic::div_mod::{
2.     lemma_div_is_ordered,
3.     lemma_fundamental_div_mod,
4.     lemma_mod_bound,
5. };
6. use vstd::arithmetic::mul::lemma_mul_inequality;
7. use vstd::arithmetic::power2::{
8.     lemma2_to64,
9.     lemma_pow2_strictly_increases,
10. };
11. use vstd::bits::lemma_usize_shr_is_div;
12. use vstd::layout::unsigned_int_max_values;
13. 
14. verus! {
15. 
16. // A frame index scaled by the frame size stays within `usize`, so `from_number`'s base-address
17. // multiply never overflows. With the corrected `FrameNumber::MAX` this follows from
18. // `FrameNumber::spec_max() <= MAX_ADDRESS / FRAME_SIZE`, hence `spec_max() * FRAME_SIZE <=
19. // (MAX_ADDRESS / FRAME_SIZE) * FRAME_SIZE <= MAX_ADDRESS == usize::MAX`. Proven in the proving phase.
20. pub proof fn lemma_from_number_no_overflow(frame: FrameNumber)
21.     requires
22.         spec_frame_raw_value(frame) <= spec_max_frame_number(),
23.     ensures
24.         spec_frame_raw_value(frame) * spec_page_size() <= usize::MAX as int,
25. {
26.     let raw: int = frame@;
27.     let s: int = spec_page_size();
28.     let m: int = usize::MAX as int;
29. 
30.     assert(s == mem::FRAME_SIZE as int);
31.     assert(m == mem::MAX_ADDRESS as int);
32. 
33.     // The corrected `spec_max()` is either `MAX_ADDRESS / FRAME_SIZE` or that minus one, so in
34.     // either case `spec_max() <= m / s`. Only this `<=` direction is needed to rule out overflow.
35.     assert(FrameNumber::spec_max() <= m / s);
36.     assert(raw <= m / s);
37. 
38.     // `(m / s) * s <= m`, since `m == s * (m / s) + (m % s)` with `0 <= m % s`.
39.     lemma_mod_bound(m, s);
40.     lemma_fundamental_div_mod(m, s);
41.     lemma_mul_inequality(raw, m / s, s);
42.     assert(raw * s <= m) by (nonlinear_arith)
43.         requires
44.             s > 0,
45.             raw * s <= (m / s) * s,
46.             m == s * (m / s) + (m % s),
47.             0 <= m % s,
48.     {
49.     }
50. }
51. 
52. // Shifting the raw address right by `FRAME_SHIFT` yields the frame index `self@ / FRAME_SIZE`,
53. // which always fits a `FrameNumber`. The shift-equals-divide step uses `FRAME_SIZE == 2^FRAME_SHIFT`;
54. // the bound uses only that the raw address is a `usize` (`raw_addr <= usize::MAX == MAX_ADDRESS`),
55. // together with the corrected `FrameNumber::spec_max() == MAX_ADDRESS / FRAME_SIZE`. No `inv()` is
56. // needed, which is exactly what makes `into_frame_number` total. Proven in the proving phase.
57. pub proof fn lemma_frame_index(
58.     addr: PhysicalAddress,
59.     raw_addr: usize,
60.     shift: usize,
61.     frame_number: usize,
62. )
63.     requires
64.         raw_addr as int == addr@,
65.         shift < 64,
66.         spec_page_size() == pow2(shift as nat),
67.         frame_number == raw_addr >> shift,
68.     ensures
69.         frame_number as int == spec_frame_number(addr@),
70.         frame_number as int <= spec_max_frame_number(),
71. {
72.     // From `spec_page_size() == pow2(shift)` and `PAGE_SIZE == 4096 == pow2(12)`, the shift is
73.     // exactly `12`, hence below `usize::BITS` on every supported target. `pow2` is strictly
74.     // increasing, so this is the only solution.
75.     lemma2_to64();
76.     assert(spec_page_size() == 4096);
77.     assert(pow2(shift as nat) == 4096);
78.     if shift < 12 {
79.         lemma_pow2_strictly_increases(shift as nat, 12);
80.         assert(false);
81.     }
82.     if shift > 12 {
83.         lemma_pow2_strictly_increases(12, shift as nat);
84.         assert(false);
85.     }
86.     assert(shift == 12);
87. 
88.     // `raw_addr >> shift == raw_addr / 2^shift == raw_addr / spec_page_size()`.
89.     lemma_usize_shr_is_div(raw_addr, shift);
90. 
91.     // Bridge the `nat` division from the shift lemma to the `int` division in
92.     // `spec_frame_number`.
93.     assert(frame_number as nat == raw_addr as nat / pow2(shift as nat));
94.     assert(frame_number as int == spec_frame_number(addr@));
95. 
96.     // The frame index is bounded by the maximum frame number. The raw address is a `usize`, so
97.     // `raw_addr <= usize::MAX == MAX_ADDRESS`; dividing both sides by the (positive) page size and
98.     // using `spec_max_frame_number() == MAX_ADDRESS / FRAME_SIZE` (the corrected formula, since
99.     // `MAX_ADDRESS % FRAME_SIZE == FRAME_SIZE - 1` for a power-of-two frame size) gives the bound.
100.     let s: int = spec_page_size();
101.     let m: int = mem::MAX_ADDRESS as int;
102.     assert(s == 4096);
103.     assert(m == usize::MAX as int);
104.     // `usize::MAX % 4096 == 4095` for any `usize` width (32 or 64): `usize::MAX == 2^BITS - 1` and
105.     // `4096 == 2^12` divides `2^BITS`, so `MAX_ADDRESS` is the last byte of its frame and the
106.     // corrected `spec_max()` selects the `MAX_ADDRESS / FRAME_SIZE` branch, equal to `m / s`.
107.     unsigned_int_max_values();
108.     assert(usize::BITS == 32 || usize::BITS == 64);
109.     if usize::BITS == 32 {
110.         assert(pow2(32) == 0x1_0000_0000) by (compute);
111.         assert(m == 0xFFFF_FFFF);
112.         assert((0xFFFF_FFFF as int) % 4096 == 4095) by (compute);
113.     } else {
114.         assert(pow2(64) == 0x1_0000_0000_0000_0000) by (compute);
115.         assert(m == 0xFFFF_FFFF_FFFF_FFFF);
116.         assert((0xFFFF_FFFF_FFFF_FFFF as int) % 4096 == 4095) by (compute);
117.     }
118.     assert(m % s == s - 1);
119.     assert(spec_max_frame_number() == m / s);
120.     assert(raw_addr as int <= m);
121.     lemma_div_is_ordered(raw_addr as int, m, s);
122.     assert(frame_number as int <= spec_max_frame_number());
123. }
124. 
125. } // verus!
