 pub proof fn lemma_from_number_no_overflow(frame: FrameNumber)
     requires
         spec_frame_raw_value(frame) <= spec_max_frame_number(),
     ensures
         spec_frame_raw_value(frame) * spec_page_size() <= usize::MAX as int,
